css:
.lb-root{position:absolute;left:64px;bottom:64px;display:flex;align-items:flex-end;gap:0;font-family:var(--lb-font);}
.lb-avatar{width:var(--lb-avatar-size);height:var(--lb-avatar-size);overflow:hidden;background:#0c0c0d;border:1px solid #3a3a3f;border-right:none;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.lb-avatar img{width:100%;height:100%;object-fit:cover;display:none;}
.lb-avatar img.is-ready{display:block;}
.lb-fallback{color:#5f5f58;font-size:40px;font-weight:800;line-height:1;}
.lb-avatar:has(img.is-ready) .lb-fallback{display:none;}
.lb-meta{background:rgba(10,10,11,.96);padding:14px 44px 16px 20px;border-bottom:6px solid var(--lb-accent);min-width:360px;}
.lb-team{display:flex;align-items:center;gap:8px;margin-bottom:2px;}
.lb-team:not(:has(.lb-team-name:not(:empty),img.is-ready)){display:none;}
.lb-team-logo{position:relative;width:var(--lb-team-logo);height:var(--lb-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.lb-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.lb-team-logo img.is-ready{display:block;}
.lb-team-fallback{width:6px;height:6px;background:var(--lb-accent);}
.lb-team-logo:has(img.is-ready) .lb-team-fallback{display:none;}
.lb-team-name{color:var(--lb-accent);font-size:var(--lb-team-size);font-weight:700;letter-spacing:2px;line-height:1.2;white-space:nowrap;max-width:460px;overflow:hidden;text-overflow:ellipsis;}
.lb-team-name:empty{display:none;}
.lb-name{color:#f4f4f0;font-size:var(--lb-name-size);font-weight:800;letter-spacing:.5px;line-height:1.05;white-space:nowrap;}
.lb-row{display:flex;align-items:center;gap:12px;margin-top:6px;}
.lb-row:not(:has(.lb-sub:not(:empty))){display:none;}
.lb-dash{width:var(--lb-dash-w);height:2px;background:var(--lb-accent);flex:0 0 auto;}
.lb-sub{color:#bdbdb6;font-size:var(--lb-sub-size);font-weight:400;line-height:1.3;white-space:nowrap;}
.lb-sub:empty{display:none;}
